mapper.update:
UPDATE conversation_contexts
SET summary = #{summary},
    summarized_through_message_id = #{summarizedThroughMessageId},
    updated_at = #{now}
WHERE user_id = #{userId}

UPDATE conversation_contexts
SET last_intent = #{lastIntent},
    last_confidence = #{lastConfidence}::NUMERIC(5,4),
    last_resolved_message_id = #{lastResolvedMessageId},
    updated_at = #{now}
WHERE user_id = #{userId}
